import React from "react";
import Banner from "./Banner";
import "../styles/Gallery.css"; // make sure only this CSS contains gallery styles

const Gallery = () => {
  const images = Array.from({ length: 16 }, (_, i) => `/assets/GalleryImg${i + 1}.jpg`);

  return (
    <>
      <Banner />
      <div className="gallery-page" style={{ margin: "0 auto" }}>
        <h2>Gallery</h2>
        <div className="gallery-grid">
          {images.map((img, idx) => (
            <div className="gallery-card" key={idx}>
              <img
                src={img}
                alt={`Gallery ${idx + 1}`}
                onError={(e) => (e.target.src = "/assets/placeholder.jpg")}
              />
            </div>
          ))}
        </div>
      </div>
    </>
  );
};

export default Gallery;
